import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import {load} from 'cheerio';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';import {verificationScreenshot} from '../../engine/verify-screenshot.mjs';import {visualScore} from '../../engine/verify.mjs';import {parseContent,YAML} from '../../scripts/source-project.mjs';
const artifact=path.resolve('artifacts/platform/cf7-heldout'),temp=await mkdtemp(path.join(tmpdir(),'cf7-heldout-')),source=path.join(artifact,'project');let browser,server;const visuals=[],checks=[];
try{
 await cp(source,temp,{recursive:true});for(const file of ['form-export.mjs','component-forms.js'])await cp(path.resolve('scripts',file),path.join(temp,'scripts',file));server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const route of ['studio-news','studio-visit'])for(const width of [1440,390]){
  const page=await browser.newPage({viewport:{width,height:900},reducedMotion:'reduce'});await page.goto(server.url+'/'+route+'/',{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);
  assert.equal(await page.locator('form.wpcf7-form input[type=submit]').isDisabled(),true);assert.equal(await page.locator('script[data-cloner-component=forms]').count(),0);
  const file=path.join(artifact,route+'-'+width+'-rebuilt.png');await verificationScreenshot(page,file,{fullPage:true});const pixel=visualScore(await readFile(path.join('work/cf7-heldout',route+'-'+width+'.png')),await readFile(file));assert.ok(pixel>=.99,route+' '+width+' visual mismatch '+pixel);visuals.push({route,width,pixel,disconnected:true});await page.close();
 }
 await browser.close();browser=null;await server.close();server=null;
 const config=JSON.parse(await readFile(path.join(temp,'forms.json'))),news=config.forms.find(f=>f.route==='/studio-news/'),visit=config.forms.find(f=>f.route==='/studio-visit/');
 for(const form of [news,visit])form.delivery={endpoint:'/heldout-delivery',format:'multipart'};
 news.fields.find(f=>f.name==='full-name').label='Preferred name';Object.assign(news.fields.find(f=>f.name==='topics[]'),{minItems:2,maxItems:2});news.fields.find(f=>f.name==='topics[]').options.push({value:'Conservation',label:'Conservation'});visit.fields.find(f=>f.name==='brief').maxFileBytes=16;
 await writeFile(path.join(temp,'forms.json'),JSON.stringify(config,null,2));
 for(const route of ['studio-news','studio-visit']){const file=path.join(temp,'content/pages',route+'.md'),p=parseContent(await readFile(file,'utf8'),file);p.meta.title='Authored '+route;p.body=p.body.replace('Independent block-theme fixture. No messages are delivered.','Authored introduction for '+route+'.');await writeFile(file,'---\n'+YAML.stringify(p.meta)+'---\n'+p.body);}
 await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});
 for(const route of ['studio-news','studio-visit']){const $=load(await readFile(path.join(temp,'output',route,'index.html'),'utf8'));assert.equal($('h1').text().trim(),'Authored '+route);assert.match($('main').text(),new RegExp('Authored introduction for '+route));}
 server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const route of ['studio-news','studio-visit'])for(const width of [1440,390]){
  const page=await browser.newPage({viewport:{width,height:900}});let posts=0,bodies=[];await page.route('**/heldout-delivery',async r=>{posts++;bodies.push(r.request().postData());await r.fulfill({status:200,contentType:'application/json',body:'{"ok":true}'});});await page.goto(server.url+'/'+route+'/',{waitUntil:'networkidle'});const form=page.locator('form.wpcf7-form'),valid=()=>form.evaluate(f=>f.checkValidity());assert.equal(await valid(),false);
  if(route==='studio-news'){
   assert.match(await page.locator('[name="full-name"]').locator('xpath=ancestor::label').innerText(),/Preferred name/);await page.locator('[name="full-name"]').fill('Fixture visitor');await page.locator('[name="subscriber-email"]').fill('fixture@example.test');await page.locator('[name="newsletter-policy"]').check();assert.equal(await valid(),false);await page.locator('[name="topics[]"]').selectOption(['Architecture']);assert.equal(await valid(),false);await page.locator('[name="topics[]"]').selectOption(['Architecture','Materials','Conservation']);assert.equal(await valid(),false);await page.locator('[name="topics[]"]').selectOption(['Architecture','Conservation']);assert.equal(await valid(),true);
  }else{
   await page.locator('[name=telephone]').fill('123456789');await page.locator('[name=website]').fill('https://example.test/');await page.locator('[name=visitors]').fill('4');await page.locator('[name="visit-date"]').fill('2027-05-10');await page.locator('[name="weekdays[]"]').first().check();assert.equal(await valid(),false);
   await page.locator('[name=brief]').setInputFiles({name:'large.txt',mimeType:'text/plain',buffer:Buffer.alloc(17)});assert.equal(await valid(),false);await page.locator('[name=brief]').setInputFiles({name:'bad.exe',mimeType:'application/octet-stream',buffer:Buffer.from('bad')});assert.equal(await valid(),false);await page.locator('[name=brief]').setInputFiles({name:'brief.txt',mimeType:'text/plain',buffer:Buffer.from('fixture')});assert.equal(await valid(),true);await page.locator('[name=visitors]').fill('3');assert.equal(await valid(),false);await page.locator('[name=visitors]').fill('4');
  }
  await form.locator('[type=submit]').click();await page.waitForFunction(()=>document.querySelector('form.wpcf7-form [role=status]')?.textContent.includes('accepted'));assert.equal(posts,1);assert.doesNotMatch(bodies[0],/_wpcf7/);if(route==='studio-news'){assert.match(bodies[0],/Architecture/);assert.match(bodies[0],/Conservation/);}checks.push({route,width,validation:true,interceptedPosts:posts});await page.close();
 }
 await writeFile(path.join(artifact,'heldout-export-check.json'),JSON.stringify({visuals,checks,markdownAndFrontmatter:true,authoredFormDefinitions:true,sourceSubmissions:0,aiCalls:0},null,2));console.log(JSON.stringify({visualCases:visuals.length,interactionCases:checks.length,minimumPixel:Math.min(...visuals.map(v=>v.pixel))}));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
